var i=`0747-himbasha`;var n=`world-0747`;var t=`ER`;var s=`eastern-africa`;var o=8;var r=131;var d={en:`Himbasha`,ua:`Хімбаша`};var l={en:`Himbasha is a Eritrea classic prepared with all-purpose flour, instant yeast, whole cow milk, white sesame seeds. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Хімбаша, страва кухні країни Еритрея зі складниками: пшеничне борошно універсальне, інстантні дріжджі, цільне коров'яче молоко, білий кунжут. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 65 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 65 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:65,i:[[`all-purpose-flour`,480,`g`],[`instant-yeast`,8,`g`],[`water`,230,`ml`],[`whole-cow-milk`,85,`ml`],[`white-granulated-sugar`,45,`g`],[`table-salt`,5,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`ground-cardamom`,4,`g`],[`white-sesame-seeds`,40,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 25 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 25 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:25,i:[]},{en:`Brush the braided or round proofed himbasha with beaten egg and bake at 180°C until golden and cooked through.`,ua:`Змастіть сформований хімбаш збитим яйцем і випікайте при 180°C до золотистості й повної готовності.`,t:[`roasting`],m:30,i:[[`chicken-egg`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[]}];var g={slug:i,id:n,country:`ER`,region:s,servings:8,minutes:131,title:d,text:l,steps:h};export{t as country,g as default,n as id,r as minutes,s as region,o as servings,i as slug,h as steps,l as text,d as title};